INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(10,N'Ghế sofa Chandley','ghe-sofa-chandley',7,N'Mô tả Ghế sofa Chandley nổi bật với thiết kế sofa góc hiện đại, đường nét vuông vức và tinh giản. Tông màu trung tính kết hợp chi tiết gỗ tạo cảm giác ấm áp, sang trọng, dễ dàng hòa hợp với nhiều phong cách nội thất khác nhau. Sofa được bọc vải cao cấp mềm mại, thoáng khí, mang lại cảm giác êm ái khi sử dụng. Đệm ngồi dày dặn cùng phần tựa lưng chắc chắn giúp nâng đỡ cơ thể tốt, phù hợp cho cả sinh hoạt hằng ngày lẫn những buổi thư giãn dài. Khung gỗ bền chắc đảm bảo độ ổn định và tuổi thọ lâu d',N'Blanc',N'Vải bố / Gỗ / Gỗ tần bì',115.0,73.0,45.0,14290000,NULL,88,110,0,1,GETDATE(),GETDATE());
