INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(12,N'Ghế sofa giường Sintra tay rời','ghe-sofa-giuong-sintra-tay-roi',7,N'Mô tả Mang vẻ đẹp tinh tế và ấm cúng, Sintra là chiếc sofa lý tưởng cho không gian sống hiện đại. Được bọc vải bố bông mềm mịn, Sintra mang lại cảm giác êm ái, dễ chịu khi ngồi hay nằm thư giãn. Điểm nhấn đặc biệt là phần decor ốp gỗ tự nhiên, tạo nên sự sang trọng và gần gũi với thiên nhiên. Thiết kế tối giản nhưng đầy phong cách giúp Sintra dễ dàng kết hợp với nhiều phong cách nội thất khác nhau Mô tả sản phẩm Chất liệu vải bọc Vải bố Tuỳ chọn chất liệu khác Chất liệu khung ghế Gỗ Loại đệm mút',N'Blanc',N'Vải bố / Gỗ / Sắt sơn tĩnh điện',180.0,75.0,46.0,21890000,NULL,7,285,0,1,GETDATE(),GETDATE());
