INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(18,N'Ghế sofa giường Puffy','ghe-sofa-giuong-puffy',7,N'Mô tả Puffy – Chiếc sofa phồng bọc da cao cấp sẽ là lựa chọn hoàn hảo! Với thiết kế êm ái, sang trọng, Puffy không chỉ là chiếc ghế sofa lý tưởng để thư giãn mà còn có thể mở rộng thành giường tiện lợi, đáp ứng mọi nhu cầu sử dụng. Chất liệu da mềm mịn, bền bỉ, dễ vệ sinh, kết hợp với lớp đệm dày giúp bạn tận hưởng cảm giác êm ái tuyệt đối. Mô tả sản phẩm Chất liệu vải bọc Da vi sợi Tuỳ chọn chất liệu khác Chất liệu khung ghế Sắt Loại đệm mút Doux Chất liệu chân ghế Sắt sơn tĩnh điện Đệm DOUX Mậ',N'Blanc',N'Da vi sợi / Sắt / Sắt sơn tĩnh điện',180.0,600.0,35.0,14690000,NULL,51,73,0,1,GETDATE(),GETDATE());
