INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(19,N'Ghế sofa giường Tess','ghe-sofa-giuong-tess',7,N'Mô tả Tess – Sofa tiện lợi, biến hóa linh hoạt! Với thiết kế thông minh, Tess không chỉ là một chiếc sofa êm ái mà còn có thể mở nệm gấp thành giường chỉ trong vài giây. Chất liệu cao cấp, đệm dày mềm mại mang đến cảm giác thoải mái tối đa khi ngồi hay nằm. Kiểu dáng thanh lịch, hiện đại, phù hợp với mọi không gian sống. Mô tả sản phẩm Chất liệu vải bọc Vải bố Tuỳ chọn chất liệu khác Chất liệu khung ghế Gỗ Loại đệm mút Doux Chất liệu chân ghế Sắt sơn tĩnh điện Đệm DOUX Mật độ của mút đệm đạt 38k',N'Blanc',N'Vải bố / Gỗ / Sắt sơn tĩnh điện',175.0,66.0,46.0,14290000,NULL,100,130,0,1,GETDATE(),GETDATE());
