INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(33,N'Ghế xoay Bado kèm đôn','ghe-xoay-bado-kem-on',7,N'Mô tả Một chỗ ngồi thoải mái để thư giãn, đặc biệt dành cho những buổi chiều hoặc những buổi tối lười biếng. Ghế xoay Bado là sản phẩm bổ sung cho sự hoàn hảo trong khu vực phòng khách, đem lại phong cách cá tính và mới mẻ cho căn phòng. Chiếc ghế có thiết kế tiện dụng với kết cấu đệm bọt biển đàn hồi cao và lớp vỏ vải da cao cấp, làm cho mỗi sản phẩm trở nên hấp dẫn về mặt thị giác và hấp dẫn về mặt thể chất. Mô tả sản phẩm Chất liệu vải bọc Da PU Tuỳ chọn chất liệu khác Chất liệu khung ghế Gỗ ',N'Blanc',N'Da PU / Gỗ',7.0,3.39,1.0,15990000,NULL,6,37,0,1,GETDATE(),GETDATE());
