INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(38,N'Ghế sofa giường Lubben','ghe-sofa-giuong-lubben',7,N'Mô tả Ghế sofa giường Lubben với thiết kế thông minh, có thể biến đổi công năng trong chốc lát. Tận dụng tối đa không gian sống và mang lại cảm giác thư giãn! Khung làm từ plywood kết hợp khung sắt chắc chắn, cùng vải bọc mềm mại chắc chắn sẽ mang lại cho bạn cảm giác thoải mái nhất. Mô tả sản phẩm Chất liệu vải bọc Vải nỉ nhung Tuỳ chọn chất liệu khác Chất liệu khung ghế Sắt Loại đệm mút Doux Chất liệu chân ghế Sắt sơn tĩnh điện Đệm DOUX Mật độ của mút đệm đạt 38kg/m3 - tính đàn hồi của nệm luô',N'Blanc',N'Vải nỉ nhung / Sắt / Sắt sơn tĩnh điện',7.0,43.29,1.0,16790000,NULL,30,28,0,1,GETDATE(),GETDATE());
