INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(39,N'Ghế sofa Vicker','ghe-sofa-vicker',7,N'Mô tả Muốn biến tấu không gian phòng khách của bạn trở nên mới lạ và độc đáo hơn, vậy bạn không nên bỏ qua mẫu ghế Vicker tiện dụng này của BLANC'' nha! Sử dụng da vi sợi cao cấp, không gây kích ứng da và dễ dàng vệ sinh. Khung ghế chắc chắn, bền, tạo cảm giác vô cùng thoải mái khi sử dụng. Với hai khối ghế linh động sắp xếp theo không gian nhà bạn. Mô tả sản phẩm Chất liệu vải bọc Da vi sợi Tuỳ chọn chất liệu khác Chất liệu khung ghế Gỗ Loại đệm mút Doux Chất liệu chân ghế Sắt sơn tĩnh điện Đệm',N'Blanc',N'Da vi sợi / Gỗ / Sắt sơn tĩnh điện',7.0,43.29,1.0,30190000,NULL,36,19,0,1,GETDATE(),GETDATE());
