INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(57,N'Ghế Rainbow','ghe-rainbow',7,N'Mô tả Sự mềm mại và độc đáo của chiếc ghế Rainbow sẽ khiến căn phòng của bạn thêm bừng sáng. Sử dụng vải lông cừu xù nhẹ cao cấp, không gây kích ứng da phù hợp với gia đình có trẻ em và người lớn tuổi. Ghế được làm bằng khung kim loại nên vô cùng chắc chắn, bền, tạo cảm giác vô cùng thoải mái khi sử dụng. Mô tả sản phẩm Chất liệu vải bọc Vải nỉ bông lông cừu Tuỳ chọn chất liệu khác Chất liệu khung ghế Sắt Loại đệm mút N/A Chất liệu chân ghế Nhựa Đệm DOUX Mật độ của mút đệm đạt 38kg/m3 - tính đàn',N'Blanc',N'Vải nỉ bông lông cừu / Sắt / Nhựa',1.0,3.39,1.0,4790000,NULL,29,178,0,1,GETDATE(),GETDATE());
