INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(117,N'Ghế Addo','ghe-addo',14,N'Mô tả Những chiếc bàn ăn sang trọng làm sao có thể thiếu được chiếc ghế Addo hiện đại này, đừng bỏ lỡ bạn nhé! Sử dụng da siêu sợi, không gây kích ứng da phù hợp với gia đình có trẻ em và người lớn tuổi. Khung ghế làm bằng sắt chắc chắn, bền, tạo cảm giác vô cùng thoải mái khi sử dụng. Bạn có thể tùy chọn loại vải theo sở thích. Mô tả sản phẩm Chất liệu vải bọc Da siêu sợi Tuỳ chọn chất liệu khác Chất liệu khung ghế Sắt Loại đệm mút Foam Chất liệu chân ghế Sắt sơn tĩnh điện Đệm DOUX Mật độ của m',N'Blanc',N'Da siêu sợi / Sắt / Sắt sơn tĩnh điện',7.0,3.39,2.935,2490000,NULL,91,207,0,1,GETDATE(),GETDATE());
