INSERT INTO Products(id,name,slug,category_id,description,brand,material,width_cm,depth_cm,height_cm,price,sale_price,stock,sold,is_featured,is_active,created_at,updated_at) VALUES(128,N'Ghế Saros','ghe-saros',14,N'Mô tả Ghế Saros với gỗ tần bì & dây giấy dó Nhật bản có thiết kế đẹp sang trọng thích hợp cho các phòng ăn của gia đình. Khung làm từ gỗ tần bì chắc chắn sẽ mang lại cho bạn cảm giác thoải mái nhất. Mô tả sản phẩm Chất liệu vải bọc Vải nỉ nhung Tuỳ chọn chất liệu khác Chất liệu khung ghế Gỗ Chất liệu chân ghế Gỗ tần bì Đệm DOUX Mật độ của mút đệm đạt 38kg/m3 - tính đàn hồi của nệm luôn dao động ở ngưỡng tỉ lệ vàng, giúp cho sofa không bị quá cứng hay quá mềm, cơ thể sẽ luôn được nâng đỡ thật nhẹ',N'Blanc',N'Vải nỉ nhung / Gỗ / Gỗ tần bì',7.0,3.39,2.935,2790000,NULL,92,108,0,1,GETDATE(),GETDATE());
