-- ============================================================
-- DAVINCI FURNITURE – Full Database Schema + Seed Data
-- Tổng hợp từ: schema.sql + output_products.sql (707 sản phẩm)
-- Chạy file này 1 lần để tạo DB hoàn chỉnh, sẵn sàng demo
-- ============================================================

IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'DAVINCI_FURNITURE')
    CREATE DATABASE [DAVINCI_FURNITURE];
GO

USE DAVINCI_FURNITURE;
GO

-- ============================================================
-- PHẦN 1: TẠO CÁC BẢNG
-- ============================================================
-- ────────────────────────────────────────────────────────────
-- 1. USERS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Users' AND xtype='U')
CREATE TABLE Users (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    name        NVARCHAR(100)  NOT NULL,
    email       VARCHAR(150)   NOT NULL UNIQUE,
    password    VARCHAR(255)   NOT NULL,
    phone       VARCHAR(20)    NULL,
    avatar      VARCHAR(500)   NULL,
    role        VARCHAR(20)    NOT NULL DEFAULT 'user',   -- 'user' | 'admin'
    is_active   BIT            NOT NULL DEFAULT 1,
    created_at  DATETIME       NOT NULL DEFAULT GETDATE(),
    updated_at  DATETIME       NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 2. CATEGORIES
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Categories' AND xtype='U')
CREATE TABLE Categories (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    name        NVARCHAR(100)  NOT NULL,
    slug        VARCHAR(150)   NOT NULL UNIQUE,
    parent_id   INT            NULL REFERENCES Categories(id),
    image       VARCHAR(500)   NULL,
    sort_order  INT            NOT NULL DEFAULT 0,
    is_active   BIT            NOT NULL DEFAULT 1,
    created_at  DATETIME       NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 3. PRODUCTS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Products' AND xtype='U')
CREATE TABLE Products (
    id           INT IDENTITY(1,1) PRIMARY KEY,
    name         NVARCHAR(200)       NOT NULL,
    slug         VARCHAR(250)        NOT NULL UNIQUE,
    category_id  INT                 NOT NULL REFERENCES Categories(id),
    -- Thông tin chi tiết sản phẩm
    description  NVARCHAR(MAX)       NULL,
    brand        NVARCHAR(100)       NULL,
    material     NVARCHAR(100)       NULL,
    width_cm     DECIMAL(8,2)        NULL,   -- Chiều rộng (cm)
    depth_cm     DECIMAL(8,2)        NULL,   -- Chiều sâu (cm)
    height_cm    DECIMAL(8,2)        NULL,   -- Chiều cao (cm)
    -- Giá
    price        DECIMAL(18,0)       NOT NULL,
    sale_price   DECIMAL(18,0)       NULL,
    -- Kho
    stock        INT                 NOT NULL DEFAULT 0,
    sold         INT                 NOT NULL DEFAULT 0,
    -- Flags
    is_featured  BIT                 NOT NULL DEFAULT 0,
    is_active    BIT                 NOT NULL DEFAULT 1,
    created_at   DATETIME            NOT NULL DEFAULT GETDATE(),
    updated_at   DATETIME            NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 4. PRODUCT IMAGES
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='ProductImages' AND xtype='U')
CREATE TABLE ProductImages (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    product_id  INT            NOT NULL REFERENCES Products(id) ON DELETE CASCADE,
    url         VARCHAR(500)   NOT NULL,
    public_id   VARCHAR(200)   NULL,   -- Cloudinary public_id
    is_primary  BIT            NOT NULL DEFAULT 0,
    sort_order  INT            NOT NULL DEFAULT 0
);
GO

-- ────────────────────────────────────────────────────────────
-- 5. PRODUCT VARIANTS (màu / kích cỡ)
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='ProductVariants' AND xtype='U')
CREATE TABLE ProductVariants (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    product_id  INT             NOT NULL REFERENCES Products(id) ON DELETE CASCADE,
    color       NVARCHAR(50)    NULL,
    size        NVARCHAR(50)    NULL,
    price       DECIMAL(18,0)   NULL,   -- override giá nếu variant có giá riêng
    stock       INT             NOT NULL DEFAULT 0,
    sku         VARCHAR(100)    NULL
);
GO

-- ────────────────────────────────────────────────────────────
-- 6. COLLECTIONS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Collections' AND xtype='U')
CREATE TABLE Collections (
    id            INT IDENTITY(1,1) PRIMARY KEY,
    name          NVARCHAR(100)  NOT NULL,
    slug          VARCHAR(150)   NOT NULL UNIQUE,
    description   NVARCHAR(MAX)  NULL,
    banner_image  VARCHAR(500)   NULL,
    sort_order    INT            NOT NULL DEFAULT 0,
    is_active     BIT            NOT NULL DEFAULT 1,
    created_at    DATETIME       NOT NULL DEFAULT GETDATE()
);
GO

IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='CollectionProducts' AND xtype='U')
CREATE TABLE CollectionProducts (
    id             INT IDENTITY(1,1) PRIMARY KEY,
    collection_id  INT  NOT NULL REFERENCES Collections(id) ON DELETE CASCADE,
    product_id     INT  NOT NULL REFERENCES Products(id)    ON DELETE CASCADE,
    sort_order     INT  NOT NULL DEFAULT 0,
    UNIQUE (collection_id, product_id)
);
GO

-- ────────────────────────────────────────────────────────────
-- 7. VOUCHERS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Vouchers' AND xtype='U')
CREATE TABLE Vouchers (
    id           INT IDENTITY(1,1) PRIMARY KEY,
    code         VARCHAR(50)     NOT NULL UNIQUE,
    type         VARCHAR(20)     NOT NULL DEFAULT 'fixed',  -- 'fixed' | 'percent'
    value        DECIMAL(18,0)   NOT NULL,
    min_order    DECIMAL(18,0)   NOT NULL DEFAULT 0,
    max_discount DECIMAL(18,0)   NULL,   -- chỉ dùng khi type = 'percent'
    usage_limit  INT             NULL,   -- NULL = không giới hạn
    used_count   INT             NOT NULL DEFAULT 0,
    start_date   DATETIME        NULL,
    end_date     DATETIME        NULL,
    is_active    BIT             NOT NULL DEFAULT 1,
    created_at   DATETIME        NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 8. ORDERS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Orders' AND xtype='U')
CREATE TABLE Orders (
    id               INT IDENTITY(1,1) PRIMARY KEY,
    order_code       VARCHAR(30)     NOT NULL UNIQUE,
    user_id          INT             NOT NULL REFERENCES Users(id),
    -- Giao hàng
    shipping_name    NVARCHAR(100)   NOT NULL,
    shipping_phone   VARCHAR(20)     NOT NULL,
    shipping_addr    NVARCHAR(500)   NOT NULL,
    -- Tiền
    subtotal         DECIMAL(18,0)   NOT NULL DEFAULT 0,
    discount         DECIMAL(18,0)   NOT NULL DEFAULT 0,
    shipping_fee     DECIMAL(18,0)   NOT NULL DEFAULT 0,
    total            DECIMAL(18,0)   NOT NULL DEFAULT 0,
    voucher_id       INT             NULL REFERENCES Vouchers(id),
    -- Thanh toán
    payment_method   VARCHAR(20)     NOT NULL DEFAULT 'cod',  -- 'cod' | 'vnpay' | 'momo'
    payment_status   VARCHAR(20)     NOT NULL DEFAULT 'pending', -- 'pending' | 'paid' | 'failed'
    -- Trạng thái đơn
    status           VARCHAR(20)     NOT NULL DEFAULT 'pending',
        -- 'pending' | 'confirmed' | 'shipping' | 'completed' | 'cancelled'
    note             NVARCHAR(500)   NULL,
    created_at       DATETIME        NOT NULL DEFAULT GETDATE(),
    updated_at       DATETIME        NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 9. ORDER ITEMS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='OrderItems' AND xtype='U')
CREATE TABLE OrderItems (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    order_id    INT             NOT NULL REFERENCES Orders(id) ON DELETE CASCADE,
    product_id  INT             NULL REFERENCES Products(id),
    variant_id  INT             NULL REFERENCES ProductVariants(id),
    name        NVARCHAR(200)   NOT NULL,   -- snapshot tên lúc đặt
    image       VARCHAR(500)    NULL,       -- snapshot ảnh lúc đặt
    quantity    INT             NOT NULL DEFAULT 1,
    price       DECIMAL(18,0)   NOT NULL    -- snapshot giá lúc đặt
);
GO

-- ────────────────────────────────────────────────────────────
-- 10. CARTS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Carts' AND xtype='U')
CREATE TABLE Carts (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    user_id     INT      NOT NULL UNIQUE REFERENCES Users(id) ON DELETE CASCADE,
    created_at  DATETIME NOT NULL DEFAULT GETDATE(),
    updated_at  DATETIME NOT NULL DEFAULT GETDATE()
);
GO

IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='CartItems' AND xtype='U')
CREATE TABLE CartItems (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    cart_id     INT             NOT NULL REFERENCES Carts(id) ON DELETE CASCADE,
    product_id  INT             NOT NULL REFERENCES Products(id),
    variant_id  INT             NULL REFERENCES ProductVariants(id),
    quantity    INT             NOT NULL DEFAULT 1,
    price       DECIMAL(18,0)   NOT NULL
);
GO

-- ────────────────────────────────────────────────────────────
-- 11. WISHLISTS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Wishlists' AND xtype='U')
CREATE TABLE Wishlists (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    user_id     INT      NOT NULL REFERENCES Users(id) ON DELETE CASCADE,
    product_id  INT      NOT NULL REFERENCES Products(id) ON DELETE CASCADE,
    created_at  DATETIME NOT NULL DEFAULT GETDATE(),
    UNIQUE (user_id, product_id)
);
GO

-- ────────────────────────────────────────────────────────────
-- 12. REVIEWS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='Reviews' AND xtype='U')
CREATE TABLE Reviews (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    product_id  INT            NOT NULL REFERENCES Products(id) ON DELETE CASCADE,
    user_id     INT            NOT NULL REFERENCES Users(id),
    rating      TINYINT        NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment     NVARCHAR(2000) NULL,
    created_at  DATETIME       NOT NULL DEFAULT GETDATE(),
    UNIQUE (product_id, user_id)   -- mỗi user chỉ review 1 lần / sản phẩm
);
GO

-- ────────────────────────────────────────────────────────────
-- 13. BLOG POSTS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='BlogPosts' AND xtype='U')
CREATE TABLE BlogPosts (
    id            INT IDENTITY(1,1) PRIMARY KEY,
    title         NVARCHAR(300)  NOT NULL,
    slug          VARCHAR(350)   NOT NULL UNIQUE,
    content       NVARCHAR(MAX)  NOT NULL,
    excerpt       NVARCHAR(500)  NULL,
    thumbnail     VARCHAR(500)   NULL,
    author_id     INT            NOT NULL REFERENCES Users(id),
    views         INT            NOT NULL DEFAULT 0,
    is_published  BIT            NOT NULL DEFAULT 0,
    created_at    DATETIME       NOT NULL DEFAULT GETDATE(),
    updated_at    DATETIME       NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 14. DESIGN REQUESTS
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='DesignRequests' AND xtype='U')
CREATE TABLE DesignRequests (
    id           INT IDENTITY(1,1) PRIMARY KEY,
    user_id      INT             NULL REFERENCES Users(id),  -- NULL nếu khách vãng lai
    full_name    NVARCHAR(100)   NOT NULL,
    phone        VARCHAR(20)     NOT NULL,
    email        VARCHAR(150)    NOT NULL,
    description  NVARCHAR(2000)  NULL,
    status       VARCHAR(20)     NOT NULL DEFAULT 'pending', -- 'pending' | 'processing' | 'done'
    created_at   DATETIME        NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 15. USER INTERACTIONS (dữ liệu cho Recommender)
--     Ghi lại: xem sản phẩm, thêm vào wishlist, đặt mua.
--     score: view=1, wishlist=3, purchase=5
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sysobjects WHERE name='UserInteractions' AND xtype='U')
CREATE TABLE UserInteractions (
    id          INT IDENTITY(1,1) PRIMARY KEY,
    user_id     INT          NOT NULL REFERENCES Users(id) ON DELETE CASCADE,
    product_id  INT          NOT NULL REFERENCES Products(id) ON DELETE CASCADE,
    type        VARCHAR(20)  NOT NULL,  -- 'view' | 'wishlist' | 'purchase'
    score       FLOAT        NOT NULL DEFAULT 1.0,
    created_at  DATETIME     NOT NULL DEFAULT GETDATE()
);
GO

-- ────────────────────────────────────────────────────────────
-- 16. INDEXES – tăng tốc các query phổ biến
-- ────────────────────────────────────────────────────────────
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_Products_CategoryId')
    CREATE INDEX IX_Products_CategoryId ON Products(category_id);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_Products_IsActive')
    CREATE INDEX IX_Products_IsActive ON Products(is_active);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_Orders_UserId')
    CREATE INDEX IX_Orders_UserId ON Orders(user_id);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_Orders_Status')
    CREATE INDEX IX_Orders_Status ON Orders(status);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_OrderItems_OrderId')
    CREATE INDEX IX_OrderItems_OrderId ON OrderItems(order_id);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_CartItems_CartId')
    CREATE INDEX IX_CartItems_CartId ON CartItems(cart_id);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_Reviews_ProductId')
    CREATE INDEX IX_Reviews_ProductId ON Reviews(product_id);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_UserInteractions_UserId')
    CREATE INDEX IX_UserInteractions_UserId ON UserInteractions(user_id);
IF NOT EXISTS (SELECT * FROM sys.indexes WHERE name='IX_UserInteractions_ProductId')
    CREATE INDEX IX_UserInteractions_ProductId ON UserInteractions(product_id);
GO

PRINT 'Schema DAVINCI_FURNITURE created successfully.';
GO

