-- ============================================================
-- PHẦN 3: SEED DATA – Categories + 50 Fake Users + 707 Sản phẩm
--         (dữ liệu từ output_products.sql Bước 3-6)
-- ============================================================
-- ============================================================
-- BƯỚC 3: Categories - xóa slug trùng trước, rồi upsert theo id
-- ============================================================
SET IDENTITY_INSERT Categories ON;

-- Xóa slug trùng ở row KHÁC id để tránh UNIQUE conflict
UPDATE Categories SET slug = slug + '-old' WHERE id NOT IN (1,2,3,4,7,8,10,11,13,14,16,17,18) AND slug IN ('phong-khach','phong-ngu','phong-an','van-phong','sofa-ghe-thu-gian','ban-tra-ke-tivi','giuong-ngu','tu-quan-ao','ban-an','ghe-an','ban-lam-viec','ghe-van-phong','ke-sach');

-- Upsert từng category theo id (không đụng slug của row khác)
UPDATE Categories SET name=N'Phòng khách',   slug='phong-khach',       parent_id=NULL, sort_order=1,  is_active=1 WHERE id=1;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(1,N'Phòng khách','phong-khach',NULL,NULL,1,1);

UPDATE Categories SET name=N'Phòng ngủ',     slug='phong-ngu',         parent_id=NULL, sort_order=2,  is_active=1 WHERE id=2;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(2,N'Phòng ngủ','phong-ngu',NULL,NULL,2,1);

UPDATE Categories SET name=N'Phòng ăn',      slug='phong-an',          parent_id=NULL, sort_order=3,  is_active=1 WHERE id=3;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(3,N'Phòng ăn','phong-an',NULL,NULL,3,1);

UPDATE Categories SET name=N'Văn phòng',     slug='van-phong',         parent_id=NULL, sort_order=4,  is_active=1 WHERE id=4;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(4,N'Văn phòng','van-phong',NULL,NULL,4,1);

UPDATE Categories SET name=N'Sofa & Ghế thư giãn', slug='sofa-ghe-thu-gian', parent_id=1, sort_order=10, is_active=1 WHERE id=7;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(7,N'Sofa & Ghế thư giãn','sofa-ghe-thu-gian',1,NULL,10,1);

UPDATE Categories SET name=N'Bàn trà & Kệ tivi', slug='ban-tra-ke-tivi', parent_id=1, sort_order=20, is_active=1 WHERE id=8;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(8,N'Bàn trà & Kệ tivi','ban-tra-ke-tivi',1,NULL,20,1);

UPDATE Categories SET name=N'Giường ngủ',   slug='giuong-ngu',        parent_id=2, sort_order=10, is_active=1 WHERE id=10;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(10,N'Giường ngủ','giuong-ngu',2,NULL,10,1);

UPDATE Categories SET name=N'Tủ quần áo',   slug='tu-quan-ao',        parent_id=2, sort_order=20, is_active=1 WHERE id=11;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(11,N'Tủ quần áo','tu-quan-ao',2,NULL,20,1);

UPDATE Categories SET name=N'Bàn ăn',       slug='ban-an',            parent_id=3, sort_order=10, is_active=1 WHERE id=13;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(13,N'Bàn ăn','ban-an',3,NULL,10,1);

UPDATE Categories SET name=N'Ghế ăn',       slug='ghe-an',            parent_id=3, sort_order=20, is_active=1 WHERE id=14;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(14,N'Ghế ăn','ghe-an',3,NULL,20,1);

UPDATE Categories SET name=N'Bàn làm việc', slug='ban-lam-viec',      parent_id=4, sort_order=10, is_active=1 WHERE id=16;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(16,N'Bàn làm việc','ban-lam-viec',4,NULL,10,1);

UPDATE Categories SET name=N'Ghế văn phòng',slug='ghe-van-phong',     parent_id=4, sort_order=20, is_active=1 WHERE id=17;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(17,N'Ghế văn phòng','ghe-van-phong',4,NULL,20,1);

UPDATE Categories SET name=N'Kệ sách',      slug='ke-sach',           parent_id=4, sort_order=30, is_active=1 WHERE id=18;
IF @@ROWCOUNT=0 INSERT INTO Categories(id,name,slug,parent_id,image,sort_order,is_active) VALUES(18,N'Kệ sách','ke-sach',4,NULL,30,1);

SET IDENTITY_INSERT Categories OFF;
PRINT 'Buoc 3 xong - Categories OK';
GO

