-- Gán sản phẩm vào collections (sample)
-- Collection 1: Bắc Âu → sofa/ghế (category 7)
SELECT 1, id, ROW_NUMBER() OVER (ORDER BY id)
FROM Products WHERE category_id=7 AND id NOT IN (SELECT product_id FROM CollectionProducts WHERE collection_id=1);

-- Collection 2: Hiện đại → bàn làm việc (category 16)
SELECT 2, id, ROW_NUMBER() OVER (ORDER BY id)
FROM Products WHERE category_id=16 AND id NOT IN (SELECT product_id FROM CollectionProducts WHERE collection_id=2);

-- Collection 3: Phòng khách → sofa + bàn trà (category 7,8)
SELECT 3, id, ROW_NUMBER() OVER (ORDER BY id)
FROM Products WHERE category_id IN (7,8) AND id NOT IN (SELECT product_id FROM CollectionProducts WHERE collection_id=3);

-- Collection 4: Văn phòng → bàn làm việc + ghế vp (category 16,17)
SELECT 4, id, ROW_NUMBER() OVER (ORDER BY id)
FROM Products WHERE category_id IN (16,17) AND id NOT IN (SELECT product_id FROM CollectionProducts WHERE collection_id=4);
GO

